#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Sets up Supabase and Vercel for Animal Logger.
# Run from the repo root:  bash scripts/setup-supabase-vercel.sh
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Supabase project, SQL, keys, checks, Vercel, and a worker smoke test.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

[[ -f supabase/schema.sql ]] || { echo "Run this from the repo root (supabase/schema.sql not found)."; exit 1; }

# copy_file PATH puts a file on the clipboard if a clipboard tool exists. Returns 1 if none does.
copy_file() {
  if   command -v wl-copy >/dev/null 2>&1; then wl-copy < "$1"
  elif command -v xclip   >/dev/null 2>&1; then xclip -selection clipboard < "$1"
  elif command -v xsel    >/dev/null 2>&1; then xsel --clipboard --input < "$1"
  elif command -v pbcopy  >/dev/null 2>&1; then pbcopy < "$1"
  elif command -v clip.exe >/dev/null 2>&1; then clip.exe < "$1"
  else return 1; fi
}

# run_sql_file PATH walks the human through pasting a SQL file into the Supabase SQL editor.
run_sql_file() {
  local file="$1"
  open_url "https://supabase.com/dashboard/project/${REF}/sql/new"
  if copy_file "$file"; then
    step "The contents of $file are on your clipboard. Click in the editor and paste (Ctrl/Cmd-V)."
  else
    step "No clipboard tool found. Open $file in your editor, select all, copy, and paste it into the SQL editor."
  fi
  step "Click Run (bottom right). If it warns about a destructive operation, read it, then confirm."
  step "You should see 'Success. No rows returned'."
}

banner "Animal Logger: Supabase + Vercel setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create the Supabase project"
say "One person (the integrator) creates the project; everyone else gets keys from them."
open_url "https://supabase.com/dashboard/new"
step "Sign in (GitHub login is fine), pick or create an organization."
step "Name: animal-logger. Choose a region close to you. Set a database password and save it somewhere safe."
step "Click Create new project and wait until it finishes setting up (about 2 minutes)."
pause "Project is ready and you can see its dashboard?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Copy the project URL and API keys"
say "These go into .env, which is gitignored. They never get committed."
step "On the project dashboard, find the Project URL (looks like https://abcdxyz.supabase.co)."
while true; do
  ask SUPABASE_URL "Paste the Project URL:"
  SUPABASE_URL="${SUPABASE_URL%/}"
  [[ "$SUPABASE_URL" =~ ^https://([a-z0-9]+)\.supabase\.co$ ]] && break
  warn "That doesn't look like https://<ref>.supabase.co; try again."
done
REF="${BASH_REMATCH[1]}"
open_url "https://supabase.com/dashboard/project/${REF}/settings/api"
note "If that page looks different, open Project Settings and find 'API keys'."
step "Copy the public key: 'anon' (legacy tab) or the 'publishable' key (sb_publishable_...). Safe for the browser."
ask_secret VITE_SUPABASE_ANON_KEY "Paste the anon / publishable key (hidden):"
step "Copy the secret key: 'service_role' (legacy tab) or the 'secret' key (sb_secret_...). Reveal it first."
warn "The secret key lets anyone write to your database. Never paste it in chat, git or the web app."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the service_role / secret key (hidden):"
VITE_SUPABASE_URL="$SUPABASE_URL"
write_env SUPABASE_URL "$SUPABASE_URL"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the tables (schema.sql)"
say "Cameras, species, sightings, predictions, security rules, realtime and the snapshots bucket."
run_sql_file supabase/schema.sql
pause "Did it say Success?"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create chat and comments (social.sql)"
say "Anonymous chat rooms and sighting comments, with length limits and a rate limit."
run_sql_file supabase/social.sql
pause "Did it say Success?"

stage "Create user pings (pings.sql)"
say "The globe's Drop ping button writes here. Locations are rounded to about 500 m by the database."
run_sql_file supabase/pings.sql
pause "Did it say Success?"

stage "Add the Katmai cameras (katmai-cams.sql)"
say "Three explore.org live-video cameras at Brooks Falls, so Katmai has cameras in the app."
run_sql_file supabase/katmai-cams.sql
pause "Did it say Success?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Load the synthetic demo data (seed.sql)"
say "Made-up sightings so the feed isn't empty. They are labelled replay; they are not real."
if [[ -x ml/.venv/bin/python ]] && confirm "Regenerate seed.sql so the timestamps are recent?"; then
  ml/.venv/bin/python ml/make_seed.py
else
  note "Using the committed supabase/seed.sql (its timestamps are from when it was generated)."
fi
run_sql_file supabase/seed.sql
note "If it says 'sightings is not empty', the seed already ran. That is fine; skip it."
pause "Done (or already loaded)?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check that the database answers"
say "The wizard calls your project's API with the public key, the same way the web app will."
code=$(curl -s -o /dev/null -w '%{http_code}' -H "apikey: $VITE_SUPABASE_ANON_KEY" -H "Authorization: Bearer $VITE_SUPABASE_ANON_KEY" "$SUPABASE_URL/rest/v1/species?select=id&limit=1" || true)
if [[ "$code" == "200" ]]; then say "✓ species table reachable with the public key (HTTP 200)."
else warn "species returned HTTP $code. Re-check the URL and public key, and that schema.sql ran."; fi
rng=$(curl -s -D - -o /dev/null -H "apikey: $VITE_SUPABASE_ANON_KEY" -H "Authorization: Bearer $VITE_SUPABASE_ANON_KEY" -H "Prefer: count=exact" -H "Range: 0-0" "$SUPABASE_URL/rest/v1/sightings?select=id" | tr -d '\r' | grep -i '^content-range' || true)
say "sightings rows: ${rng:-unknown} (the number after the slash; 0 means the seed has not loaded)"
bc=$(curl -s -o /dev/null -w '%{http_code}' -H "apikey: $SUPABASE_SERVICE_ROLE_KEY" -H "Authorization: Bearer $SUPABASE_SERVICE_ROLE_KEY" "$SUPABASE_URL/storage/v1/bucket/snapshots" || true)
if [[ "$bc" == "200" ]]; then say "✓ 'snapshots' storage bucket exists."
else warn "Could not confirm the snapshots bucket (HTTP $bc). Check Storage in the dashboard; create a public bucket named snapshots if missing."; fi
pause "Continue?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Deploy the web app to Vercel"
say "The web app is static; the worker never runs on Vercel."
open_url "https://vercel.com/new"
step "Sign in with GitHub and import waychlate/knighthacks2026 (grant Vercel access to the repo if asked)."
step "Branch: main. Set Root Directory to: web"
step "Framework preset should say Vite. Build command: npm run build. Output directory: dist."
step "Open Environment Variables and add these two (names exact):"
note "    VITE_SUPABASE_URL = $VITE_SUPABASE_URL"
note "    VITE_SUPABASE_ANON_KEY = the public key you copied (NOT the secret/service_role key)"
step "Click Deploy and wait for it to finish."
ask DEPLOYED_URL "Paste the deployed URL (https://...vercel.app):"
DEPLOYED_URL="${DEPLOYED_URL%/}"
write_env DEPLOYED_URL "$DEPLOYED_URL"
if curl -s -L --max-time 20 "$DEPLOYED_URL" | grep -q "Animal Logger"; then say "✓ the deployed page responds and looks like Animal Logger."
else warn "Could not confirm the page at $DEPLOYED_URL. Open it in a browser and check."; fi
note "Seed rows are 'Demo clip' data. If the page still says 'Showing mock data', the env vars were not set at build time: add them in Vercel, then redeploy."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Smoke test: the real pipeline writes to Supabase"
say "This runs YOLO + BioCLIP on a recorded bison clip and inserts real sightings (marked replay)."
CLIP="worker/sample_videos/nps/yell-Bison00772MTS_1280x720.mp4"
if [[ ! -x worker/.venv/bin/python || ! -f "$CLIP" ]]; then
  warn "Need worker/.venv and $CLIP (see README, section 3). Skipping this stage."
  SKIPPED+=("worker smoke test (set up worker/.venv and the sample clip, then run it)")
elif confirm "Insert a few real replay sightings into your database now?"; then
  ( cd worker && .venv/bin/python -m animal_worker.main --source "sample_videos/nps/yell-Bison00772MTS_1280x720.mp4" \
      --camera "Lamar Valley Demo Cam" --park yellowstone ) 2>&1 | grep -E "SIGHTING|Error|error|Traceback" || true
  step "Open your deployed site (Demo mode) and the Supabase Table Editor: new rows should appear."
  pause "Did new sightings show up?"
else
  SKIPPED+=("worker smoke test (run the worker without --dry-run once keys are in .env)")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
